B.ah1=new A.qW("Doa Sholat Dhuha","\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0636\u0651\u064f\u062d\u064e\u0627\u0621\u064e \u0636\u064f\u062d\u064e\u0627\u0624\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u0647\u064e\u0627\u0621\u064e \u0628\u064e\u0647\u064e\u0627\u0624\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u062c\u064e\u0645\u064e\u0627\u0644\u064e \u062c\u064e\u0645\u064e\u0627\u0644\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0642\u064f\u0648\u0651\u064e\u062a\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u062f\u0652\u0631\u064e\u0629\u064e \u0642\u064f\u062f\u0652\u0631\u064e\u062a\u064f\u0643\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u0650\u0635\u0652\u0645\u064e\u0629\u064e \u0639\u0650\u0635\u0652\u0645\u064e\u062a\u064f\u0643\u064e. \u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0631\u0650\u0632\u0652\u0642\u0650\u064a\u0652 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0641\u064e\u0623\u064e\u0646\u0652\u0632\u0650\u0644\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u0650\u062c\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0645\u064f\u0639\u0652\u0633\u0650\u0631\u064b\u0627 \u0641\u064e\u064a\u064e\u0633\u0650\u0651\u0631\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u062d\u064e\u0631\u064e\u0627\u0645\u064b\u0627 \u0641\u064e\u0637\u064e\u0647\u0650\u0651\u0631\u0652\u0647\u064f \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u0628\u064e\u0639\u0650\u064a\u0652\u062f\u064b\u0627 \u0641\u064e\u0642\u064e\u0631\u0650\u0651\u0628\u0652\u0647\u064f \u0628\u0650\u062d\u064e\u0642\u0650\u0651 \u0636\u064f\u062d\u064e\u0627\u0626\u0650\u0643\u064e \u0648\u064e\u0628\u064e\u0647\u064e\u0627\u0626\u0650\u0643\u064e \u0648\u064e\u062c\u064e\u0645\u064e\u0627\u0644\u0650\u0643\u064e \u0648\u064e\u0642\u064f\u0648\u0651\u064e\u062a\u0650\u0643\u064e \u0648\u064e\u0642\u064f\u062f\u0652\u0631\u064e\u062a\u0650\u0643\u064e \u0622\u062a\u0650\u0646\u0650\u064a\u0652 \u0645\u064e\u0627 \u0622\u062a\u064e\u064a\u0652\u062a\u064e \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0643\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0652\u0646\u064e","Allaahumma innadh dhuhaa-a dhuhaa-uka, wal bahaa-a bahaa-uka, wal jamaala jamaaluka, wal quwwata quwwatuka, wal qudrata qudratuka, wal 'ishmata 'ishmatuka. Allaahumma in kaana rizqii fis samaa-i fa anzilhu, wa in kaana fil ardhi fa akhrijhu, wa in kaana mu'siran fa yassirhu...","Ya Allah, sesungguhnya waktu dhuha adalah waktu dhuha-Mu, keagungan adalah keagungan-Mu, keindahan adalah keindahan-Mu, kekuatan adalah kekuatan-Mu, kekuasaan adalah kekuasaan-Mu, dan penjagaan adalah penjagaan-Mu...")
B.blR=s([B.ah1],t.Av)
B.c_6=new A.hr("Sholat Dhuha","sunnah","2 hingga 8 Rakaat - Sholat pagi pembuka rezeki","2 - 8 Rakaat","Mulai matahari setinggi tombak (sekitar pk 07.00) sampai menjelang Dzuhur","Sunnah Muakkad","Sebagai sedekah bagi 360 persendian tubuh dan Allah mencukupi kebutuhan rezeki di hari itu.",B.c_v,null,null,B.b94,B.blR)
B.c_M=new A.fl("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u0652\u0648\u0650\u062a\u0652\u0631\u0650 \u062b\u064e\u0644\u0627\u064e\u062b\u064e \u0631\u064e\u0643\u064e\u0639\u064e\u0627\u062a\u064d \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatal witri tsalaatsa raka'aatin mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Witir tiga rakaat menghadap kiblat karena Allah Ta'ala.")
B.c9t=new A.d9("Tata Cara Sholat Witir 3 Rakaat","Dapat dilakukan 2 rakaat salam lalu ditambah 1 rakaat salam (lebih utama), atau langsung 3 rakaat dengan satu kali salam. Disunnahkan membaca Al-A'la pada rakaat 1, Al-Kafirun pada rakaat 2, dan Al-Ikhlas, Al-Falaq, An-Nas pada rakaat 3.",null,null,null)
B.bcC=s([B.c9t],t.I4)
B.c_c=new A.hr("Sholat Witir","sunnah","1 atau 3 Rakaat - Sholat ganjil penutup malam","1 atau 3 Rakaat (Bisa sampai 11 Rakaat)","Setelah sholat Isya hingga sebelum waktu Subuh","Sunnah Muakkad","Allah itu Maha Ganjil dan menyukai yang ganjil. Menjadi penutup rangkaian ibadah sholat malam.",B.c_M,null,null,B.bcC,null)
B.c_w=new A.fl("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u0627\u0650\u0633\u0652\u062a\u0650\u062e\u064e\u0627\u0631\u064e\u0629\u0650 \u0631\u064e\u0643\u0652\u0639\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatal istikhaarati rak'ataini mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Istikharah dua rakaat menghadap kiblat karena Allah Ta'ala.")
B.c9B=new A.d9("Tata Cara Sholat Istikharah","Dilakukan 2 rakaat. Setelah salam, membaca puji-pujian kepada Allah, shalawat, lalu membaca doa istikharah sambil menyebutkan perkara yang dihadapi.",null,null,null)
B.aBh=s([B.c9B],t.I4)
B.c_5=new A.hr("Sholat Istikharah","sunnah","2 Rakaat - Memohon petunjuk keputusan terbaik","2 Rakaat","Bisa dikerjakan kapan saja di luar waktu terlarang sholat","Sunnah","Mendapat ketenangan hati dan bimbingan Allah atas pilihan perkara hidup.",B.c_w,null,null,B.aBh,null)
B.c_x=new A.fl("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u062a\u064e\u0651\u0648\u0652\u0628\u064e\u0629\u0650 \u0631\u064e\u0643\u0652\u0639\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatat taubati rak'ataini mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Taubat dua rakaat menghadap kiblat karena Allah Ta'ala.")
B.c9W=new A.d9("Tata Cara Sholat Taubat","Sholat 2 rakaat dengan penuh penyesalan dan kekhusyukan, diakhiri istighfar dan tekad untuk tidak mengulangi perbuatan maksiat.",null,null,null)
B.bg8=s([B.c9W],t.I4)
B.c_3=new A.hr("Sholat Taubat","sunnah","2 Rakaat - Memohon ampunan atas dosa & kesalahan","2 Rakaat","Kapan saja setelah melakukan perbuatan dosa (utama di malam hari)","Sunnah","Allah mengampuni dosa hamba-Nya yang beristighfar dengan sungguh-sungguh.",B.c_x,null,null,B.bg8,null)
B.c_D=new A.fl("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0633\u064f\u0646\u064e\u0651\u0629\u064e \u0627\u0644\u0652\u062d\u064e\u0627\u062c\u064e\u0629\u0650 \u0631\u064e\u0643\u0652\u0639\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0652\u0628\u0650\u0644\u064e \u0627\u0644\u0652\u0642\u0650\u0628\u0652\u0644\u064e\u0629\u0650 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii sunnatal haajati rak'ataini mustaqbilal qiblati lillaahi ta'aalaa.","Saya berniat sholat sunnah Hajat dua rakaat menghadap kiblat karena Allah Ta'ala.")
B.c9P=new A.d9("Tata Cara Sholat Hajat","Dikerjakan 2 rakaat salam, dilanjutkan dengan membaca istighfar 100x, shalawat 100x, lalu memanjatkan doa hajat spesifik yang diinginkan.",null,null,null)
B.bfI=s([B.c9P],t.I4)
B.c_9=new A.hr("Sholat Hajat","sunnah","2 hingga 12 Rakaat - Memohon dikabulkannya hajat","2 Rakaat (sampai 12 rakaat)","Kapan saja terutama di keheningan malam hari","Sunnah","Allah memudahkan urusan dunia dan akhirat bagi hamba yang memohon kepada-Nya.",B.c_D,null,null,B.bfI,null)
B.c_B=new A.fl("\u0623\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0652 \u0639\u064e\u0644\u064e\u0649 \u0647\u0670\u0630\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u064a\u0650\u0651\u062a\u0650 (\u0627\u0644\u0652\u0645\u064e\u064a\u0650\u0651\u062a\u064e\u0629\u0650) \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e \u062a\u064e\u0643\u0652\u0628\u0650\u064a\u0652\u0631\u064e\u0627\u062a\u064d \u0641\u064e\u0631\u0652\u0636\u064e \u0643\u0650\u0641\u064e\u0627\u064a\u064e\u0629\u064d \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Ushallii 'alaa haadzal mayyiti (laki-laki) / haadzihil mayyitati (perempuan) arba'a takbiiraatin fardha kifaayatin lillaahi ta'aalaa.","Saya berniat sholat atas jenazah ini empat takbir fardhu kifayah karena Allah Ta'ala.")
B.c9m=new A.d9("Takbir Pertama (1)","Mengangkat tangan membaca takbir, lalu membaca Surah Al-Fatihah.",null,null,null)
B.c9V=new A.d9("Takbir Kedua (2)","Takbir lalu membaca Shalawat Ibrahimiyah kepada Nabi Muhammad SAW.",null,null,null)
B.c9s=new A.d9("Takbir Ketiga (3)",'Takbir lalu membaca doa ampunan untuk jenazah: "Allaahummaghfir lahu warhamhu..."',"\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f (\u0644\u064e\u0647\u064e\u0627) \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0647\u064f \u0648\u064e\u0639\u064e\u0627\u0641\u0650\u0647\u0650 \u0648\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f","Allaahummaghfir lahu (laki-laki) / lahaa (perempuan) warhamhu wa 'aafihi wa'fu 'anhu.","Ya Allah, ampunilah dia, rahmatilah dia, selamatkanlah dia dan maafkanlah kesalahannya.")
B.c9N=new A.d9("Takbir Keempat (4) & Salam","Takbir membaca doa penutup, lalu mengucap salam ke kanan dan ke kiri.",null,null,null)
B.b87=s([B.c9m,B.c9V,B.c9s,B.c9N],t.I4)
B.c_a=new A.hr("Sholat Jenazah","sunnah","4 Takbir - Tanpa ruku' & tanpa sujud","4 Takbir (Berdiri)","Kapan saja setelah jenazah dimandikan dan dikafani","Fardhu Kifayah","Mendapat pahala sebesar dua gunung Uhud (Qirath) bagi yang menyalatkan hingga menguburkan.",B.c_B,null,null,B.b87,null)
B.c_u=new A.fl("\u0646\u064e\u0648\u064e\u064a\u0652\u062a\u064f \u0627\u0644\u0652\u0648\u064f\u0636\u064f\u0648\u0652\u0621\u064e \u0644\u0650\u0631\u064e\u0641\u0652\u0639\u0650 \u0627\u0644\u0652\u062d\u064e\u062f\u064e\u062b\u0650 \u0627\u0644\u0623\u064e\u0635\u0652\u063a\u064e\u0631\u0650 \u0641\u064e\u0631\u0652\u0636\u064b\u0627 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Nawaitul wudhuu-a liraf'il hadatsil ashghari fardhan lillaahi ta'aalaa.","Saya niat berwudhu untuk menghilangkan hadats kecil fardhu karena Allah Ta'ala.")
B.c9Q=new A.d9("1. Membaca Basmalah & Mencuci Telapak Tangan","Mencuci kedua telapak tangan hingga sela-sela jari sebanyak 3 kali.",null,null,null)
B.c9y=new A.d9("2. Berkumur-kumur & Istinsyaq","Berkumur-kumur 3 kali dan menghirup air ke hidung lalu mengeluarkannya 3 kali.",null,null,null)
B.c9S=new A.d9("3. Membasuh Wajah & Niat","Membasuh seluruh wajah dari tumbuhnya rambut hingga dagu sebanyak 3 kali sambil berniat wudhu dalam hati.",null,null,null)
B.c9M=new A.d9("4. Membasuh Kedua Tangan Hingga Siku","Membasuh tangan kanan hingga siku 3 kali, lalu tangan kiri 3 kali.",null,null,null)
B.c9K=new A.d9("5. Mengusap Sebagian Kepala / Rambut","Mengusap kepala dengan air sebanyak 3 kali.",null,null,null)
B.c9Y=new A.d9("6. Membasuh Kedua Telinga","Mengusap daun telinga luar dan dalam dengan air sebanyak 3 kali.",null,null,null)
B.c9U=new A.d9("7. Membasuh Kedua Kaki Hingga Mata Kaki","Membasuh kaki kanan hingga mata kaki dan sela-sela jari 3 kali, lalu kaki kiri 3 kali.",null,null,null)
B.c9p=new A.d9("8. Tertib & Berdoa Setelah Wudhu","Melakukan seluruh rukun secara berurutan dan membaca doa setelah wudhu menghadap kiblat.",null,null,null)
B.b9N=s([B.c9Q,B.c9y,B.c9S,B.c9M,B.c9K,B.c9Y,B.c9U,B.c9p],t.I4)
B.agZ=new A.qW("Doa Setelah Berwudhu","\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0651\u064e \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064b\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0652\u0644\u064f\u0647\u064f. \u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u0650\u064a\u0652\u0646\u064e \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0637\u064e\u0647\u0650\u0651\u0631\u0650\u064a\u0652\u0646\u064e \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652\u0646\u0650\u064a\u0652 \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0643\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0652\u0646\u064e","Asyhadu allaa ilaaha illallaahu wahdahu laa syariika lah, wa asyhadu anna Muhammadan 'abduhu wa rasuuluh. Allaahummaj'alnii minat tawwaabiina waj'alnii minal mutathahhiriina waj'alnii min 'ibaadikash shaalihiin.","Aku bersaksi tiada Tuhan selain Allah Yang Maha Esa tiada sekutu bagi-Nya, dan aku bersaksi Muhammad adalah hamba dan utusan-Nya. Ya Allah, jadikanlah aku termasuk golongan orang-orang yang bertaubat, jadikanlah aku termasuk golongan orang-orang yang bersuci, dan jadikanlah aku termasuk hamba-hamba-Mu yang shalih.")
B.be2=s([B.agZ],t.Av)
B.c_b=new A.hr("Tata Cara Berwudhu","bersuci","Panduan rukun, sunnah, & doa setelah wudhu","","","Syarat Sah Sholat (Wajib Bersuci)","Menggugurkan dosa-dosa dari setiap anggota tubuh yang dibasuh bersama tetesan air wudhu.",B.c_u,null,null,B.b9N,B.be2)
B.c_I=new A.fl("\u0646\u064e\u0648\u064e\u064a\u0652\u062a\u064f \u0627\u0644\u062a\u0651\u064e\u064a\u064e\u0645\u0651\u064f\u0645\u064e \u0644\u0627\u0650\u0633\u0652\u062a\u0650\u0628\u064e\u0627\u062d\u064e\u0629\u0650 \u0627\u0644\u0635\u0651\u064e\u0644\u064e\u0627\u0629\u0650 \u0641\u064e\u0631\u0652\u0636\u064b\u0627 \u0644\u0650\u0644\u0651\u0670\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649","Nawaitut tayammuma listibaahatish shalaati fardhan lillaahi ta'aalaa.","Saya berniat tayammum untuk dapat melaksanakan sholat fardhu karena Allah Ta'ala.")
B.c9n=new A.d9("1. Meletakkan Telapak Tangan pada Debu Suci","Menepukkan kedua telapak tangan ke permukaan yang berdebu bersih dan suci, lalu meniupnya perlahan.",null,null,null)
B.c9I=new A.d9("2. Mengusap Wajah","Mengusapkan debu pada kedua tangan ke seluruh permukaan wajah sambil berniat.",null,null,null)
B.c9G=new A.d9("3. Mengusap Kedua Tangan Hingga Siku","Menepukkan tangan kembali ke debu di tempat berbeda, lalu mengusapkannya ke tangan kanan hingga siku dan tangan kiri hingga siku.",null,null,null)
B.b92=s([B.c9n,B.c9I,B.c9G],t.I4)
B.c_d=new A.hr("Tata Cara Tayammum","bersuci","Bersuci dengan debu suci saat tidak ada air","","","Rukhsah (Keringanan) Pengganti Wudhu / Mandi","Keringanan dari Allah agar ibadah sholat tetap dapat ditunaikan dalam kondisi darurat.",B.c_I,null,null,B.b92,null)
B.c9F=new A.d9("1. Membaca Istighfar (3x)","Memohon ampunan kepada Allah setelah mengucap salam.","\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u0647\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0652\u0645\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0652 \u0644\u0627\u064e \u0625\u0650\u0644\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u064e\u0651 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064f\u0651 \u0627\u0644\u0652\u0642\u064e\u064a\u064f\u0651\u0648\u0652\u0645\u064f \u0648\u064e\u0623\u064e\u062a\u064f\u0648\u0652\u0628\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 (\u0663x)","Astaghfirullaahal 'azhiimal ladzii laa ilaaha illaa huwal hayyul qayyuumu wa atuubu ilaih (3x)","Aku memohon ampun kepada Allah Yang Maha Agung, yang tiada Tuhan selain Dia, Yang Maha Hidup lagi Maha Berdiri Sendiri, dan aku bertaubat kepada-Nya.")
B.c9v=new A.d9("2. Membaca Doa Keselamatan (Allaahumma Antas Salaam)","Memuji Allah sebagai sumber kedamaian.","\u0627\u064e\u0644\u0644\u0651\u0670\u0647\u064f\u0645\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u0651\u064e\u0644\u0627\u064e\u0645\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0633\u0651\u064e\u0644\u0627\u064e\u0645\u064f \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0644\u0627\u064e\u0644\u0650 \u0648\u064e\u0627\u0644\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650","Allaahumma antas salaam wa minkas salaam tabaarakta yaa dzal jalaali wal ikraam.","Ya Allah, Engkaulah As-Salam (keselamatan) dan dari-Mu lah datangnya keselamatan, Maha Berkah Engkau wahai Dzat Yang Memiliki Keagungan dan Kemuliaan.")
B.c9x=new A.d9("3. Membaca Tasbih, Tahmid, & Takbir (masing-masing 33x)","Mengagungkan Allah sebanyak 33 kali.","\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650 (\u0663\u0663x)\n\u0627\u064e\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u0651\u0670\u0647\u0650 (\u0663\u0663x)\n\u0627\u0644\u0644\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f (\u0663\u0663x)","Subhaanallaah (33x)\nAlhamdulillaah (33x)\nAllaahu Akbar (33x)","Maha Suci Allah (33x), Segala Puji bagi Allah (33x), Allah Maha Besar (33x).")
B.c9L=new A.d9("4. Membaca Tahlil Penyempurna 100x","Membaca pengesaan Allah di akhir tasbih.","\u0644\u0627\u064e \u0625\u0650\u0644\u0670\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u0627\u064e \u0634\u064e\u0631\u0650\u064a\u0652\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0652 \u0648\u064e\u064a\u064f\u0645\u0650\u064a\u0652\u062a\u064f \u0648\u064e\u0647\u064f\u0648\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0650\u064a\u0652\u0631\u064c","Laa ilaaha illallaahu wahdahu laa syariika lah, lahul mulku wa lahul hamdu yuhyii wa yumiitu wa huwa 'alaa kulli syai-in qadiir.","Tiada Tuhan selain Allah Yang Maha Esa tiada sekutu bagi-Nya, milik-Nya kerajaan dan milik-Nya segala puji, Yang Menghidupkan dan Mematikan, dan Dia Maha Kuasa atas segala sesuatu.")
B.c9T=new A.d9("5. Membaca Ayat Kursi","Rasulullah bersabda barangsiapa membaca Ayat Kursi setiap usai sholat wajib, tidak ada yang menghalanginya masuk surga kecuali kematian.","\u0627\u0644\u0644\u0651\u0670\u0647\u064f \u0644\u064e\u0627\u0653 \u0627\u0650\u0644\u0670\u0647\u064e \u0627\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u0651\u064f \u0627\u0644\u0652\u0642\u064e\u064a\u0651\u064f\u0648\u0652\u0645\u064f\u06da \u0644\u064e\u0627 \u062a\u064e\u0627\u0652\u062e\u064f\u0630\u064f\u0647\u0657 \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u0651\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064c\u06d7 \u0644\u064e\u0647\u0657 \u0645\u064e\u0627 \u0641\u0650\u0649 \u0627\u0644\u0633\u0651\u064e\u0645\u0670\u0648\u0670\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u0649 \u0627\u0644\u0652\u0627\u064e\u0631\u0652\u0636\u0650\u06d7 \u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0652 \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u0657\u0653 \u0627\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0650\u0630\u0652\u0646\u0650\u0647\u0656\u06d7 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u064e\u064a\u0652\u062f\u0650\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0652\u0637\u064f\u0648\u0652\u0646\u064e \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0651\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0656\u0653 \u0627\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u06e4\u0621\u064e\u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u0651\u064f\u0647\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u0670\u0648\u0670\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0627\u064e\u0631\u0652\u0636\u064e\u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0640\u0654\u064f\u0648\u0652\u062f\u064f\u0647\u0657 \u062d\u0650\u0641\u0652\u0638\u064f\u0647\u064f\u0645\u064e\u0627\u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0652\u0645\u064f","Allaahu laa ilaaha illaa huwal hayyul qayyuum, laa ta'khudzuhuu sinatuw wa laa naum, lahuu maa fis samaawaati wa maa fil ardh...","Allah, tidak ada tuhan selain Dia. Yang Mahahidup, Yang terus-menerus mengurus (makhluk-Nya), tidak mengantuk dan tidak tidur. Milik-Nya apa yang ada di langit dan apa yang ada di bumi...")
